#!/usr/bin/env node
// What the addon adds to, and costs against, Storybook's own docgen, on real repositories. See docs/storybook-parity.md.
//
//   node scripts/storybook-parity.mjs --corpora ~/corpora [--only chakra,spectrum] [--out report] [--limit 50]
//
// Needs `pnpm build` (the addon's dist), the native binding, and the corpora cloned with their dependencies installed.
// Each variant runs in its own child process so its peak RSS is its own.
import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { createRequire, registerHooks } from 'node:module'
import { basename, dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { parseArgs } from 'node:util'

const here = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)

/** Where each corpus keeps its sources (one directory or several), relative to its root. */
const CORPORA = {
  mantine: { root: 'mantine', src: 'packages/@mantine/core/src' },
  chakra: { root: 'chakra-ui', src: 'packages/react/src' },
  shadcn: { root: 'shadcn-ui', src: 'apps/v4' },
  antd: { root: 'ant-design', src: 'components' },
  spectrum: { root: 'react-spectrum', src: ['packages', 'starters'] },
}

const STORY_FILE = /\.stories\.(tsx?|jsx?)$/

/** The addon variants: what the defaults do, and what the addon did before it read dependencies. */
const VARIANTS = {
  caliper: { loadDependencies: true, collapseInheritedProps: 'none' },
  'caliper-nodeps': { loadDependencies: false, collapseInheritedProps: 'none' },
  'caliper-curated': { loadDependencies: true, collapseInheritedProps: 'dependencies' },
  // The same extractions, answering for every component whatever its diagnostics say: the information the addon
  // holds, apart from how much of it the `degraded` rule lets through.
  'caliper-never': { loadDependencies: true, collapseInheritedProps: 'none', fallback: 'never' },
  'caliper-nodeps-never': { loadDependencies: false, collapseInheritedProps: 'none', fallback: 'never' },
}

/** The session alone does not depend on the fallback rule. */
const SESSION_VARIANTS = ['caliper', 'caliper-nodeps', 'caliper-curated']

/** The lazy session is the default; the eager ones resolve every component at start, as the addon did before it. */
Object.assign(VARIANTS, {
  // What the element attributes cost the session: each mode, otherwise the defaults.
  'caliper-html-none': { loadDependencies: true, collapseInheritedProps: 'none', htmlAttributes: 'none' },
  'caliper-html-curated': { loadDependencies: true, collapseInheritedProps: 'none', htmlAttributes: 'curated' },
  'caliper-html-full': { loadDependencies: true, collapseInheritedProps: 'none', htmlAttributes: 'full' },
  'caliper-eager': { loadDependencies: true, collapseInheritedProps: 'none', lazy: false },
  'caliper-nodeps-eager': { loadDependencies: false, collapseInheritedProps: 'none', lazy: false },
  // Lazy that resolves the rest in one background pass after 16 components were asked for.
  'caliper-fill': { loadDependencies: true, collapseInheritedProps: 'none', fillAfter: 16 },
  // The lazy session as it shipped in #172: warm-up on, no fill.
  'caliper-shipped': { loadDependencies: true, collapseInheritedProps: 'none', warmUp: true, fillAfter: 0 },
  // The structural answer plus the warm TypeScript 7.1 checker for the requested component (ADR 0022); `CALIPER_TSC` names
  // the `tsc` binary when the corpus does not install typescript@beta itself.
  'caliper-ondemand': {
    loadDependencies: true,
    collapseInheritedProps: 'none',
    semanticTypes: 'on-demand',
    ...(process.env.CALIPER_TSC ? { tscPath: process.env.CALIPER_TSC } : {}),
  },
})

function walk(dir, found = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules' || entry.name.startsWith('.git')) continue
    const path = join(dir, entry.name)
    if (entry.isDirectory()) walk(path, found)
    else if (STORY_FILE.test(entry.name)) found.push(path)
  }
  return found
}

/** Node reports `maxRSS` in kilobytes on every platform. */
function peakRssMb() {
  return Math.round(process.resourceUsage().maxRSS / 1024)
}

// `__docgenInfo` (react-docgen-typescript's shape) to argTypes, the way `@storybook/react`'s own docgen worker does it
// (src/docgen/buildDocgen.ts): React's `Attributes`, `RefAttributes` and `ClassAttributes` props from node_modules are
// dropped, defaults are marked `computed: false`, and React's `extractArgTypes` converts the rest. Calling React's
// converter, not a copy of it, keeps controls, type summaries and default-value summaries identical to Storybook's.

import type { RdtComponentDoc, RdtProp } from 'caliper-docgen-napi'
import type { StrictArgTypes } from 'storybook/internal/types'

/** `parameters.docs.extractArgTypes` from `@storybook/react/entry-preview-argtypes`. */
export type ExtractArgTypes = (component: { __docgenInfo: RdtComponentDoc }) => StrictArgTypes | null

const REACT_ATTRIBUTE_INTERFACES = new Set(['Attributes', 'RefAttributes', 'ClassAttributes'])

function isReactAttribute(prop: RdtProp): boolean {
  return (
    prop.parent !== null &&
    REACT_ATTRIBUTE_INTERFACES.has(prop.parent.name) &&
    /(^|[\\/])node_modules[\\/]/.test(prop.parent.fileName)
  )
}

export function toArgTypes(doc: RdtComponentDoc, extractArgTypes: ExtractArgTypes): StrictArgTypes | undefined {
  const props = Object.fromEntries(
    Object.entries(doc.props)
      .filter(([, prop]) => !isReactAttribute(prop))
      .map(([name, prop]) => [
        name,
        prop.defaultValue ? { ...prop, defaultValue: { ...prop.defaultValue, computed: false } } : prop,
      ]),
  )
  return extractArgTypes({ __docgenInfo: { ...doc, props } }) ?? undefined
}

/** React's converter, loaded on first use: it is a preview entry, so only a docgen request should pay for it. */
export async function loadExtractArgTypes(): Promise<ExtractArgTypes> {
  const { parameters } = (await import('@storybook/react/entry-preview-argtypes')) as {
    parameters: { docs: { extractArgTypes: ExtractArgTypes } }
  }
  return parameters.docs.extractArgTypes
}
