      id: `${title.toLowerCase()}--basic`,
      name: 'Basic',
      title,
      importPath: `./src/stories/${title}.stories.tsx`,
      tags: [],
    }
    // oxlint-disable-next-line unicorn/require-post-message-target-origin -- a worker has no origin
    worker.postMessage(entry)
  })
}

