import * as React from 'react'
type Dir = 'row' | 'column'
type Size = 'sm' | 'md' | 'lg'
export enum Color { Red = 'red', Blue = 'blue' }
export enum Num { A, B }
interface Point { x: number; y: number }
type Names = 'root' | 'item'

export interface ProbeProps {
  /** string literal union */ size?: Size
  /** inline literal union */ dir?: 'row' | 'column' | 'none'
  /** number literal union */ cols?: 1 | 2 | 3
  /** mixed literal union */ mixed?: 'a' | 1 | true
  /** literal + string & {} (open union) */ variant?: 'solid' | 'outline' | (string & {})
  /** literal | string */ loose?: 'a' | 'b' | string
  /** literal union with undefined/null */ nullable?: 'a' | 'b' | null
  /** TS enum */ color?: Color
  /** numeric enum */ num?: Num
  /** one member of enum */ colorOne?: Color.Red
  /** single literal */ kind?: 'button'
  /** boolean */ flag?: boolean
  /** boolean | undefined explicit */ flag2: boolean | undefined
  /** required string */ label: string
  /** number */ count?: number
  /** number | template */ width?: number | `${number}px`
  /** template literal */ tpl?: `data-${string}`
  /** callback */ onChange?: (value: string) => void
  /** callback with event */ onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  /** function no args */ onDone?: () => void
  /** method style */ render?(x: number): React.ReactNode
  /** render prop */ renderItem?: (item: Point, i: number) => React.ReactNode
  /** ReactNode */ icon?: React.ReactNode
  /** ReactElement */ element?: React.ReactElement
  /** JSX.Element */ jsx?: React.JSX.Element
  /** children */ children?: React.ReactNode
  /** ElementType */ as?: React.ElementType
  /** ComponentType */ comp?: React.ComponentType<{ a: number }>
  /** ref */ innerRef?: React.Ref<HTMLDivElement>
  /** object type */ point?: Point
  /** inline object */ obj?: { a: string; b?: number }
  /** Partial Record */ classNames?: Partial<Record<Names, string>>
  /** Record */ rec?: Record<string, number>
  /** index signature */ idx?: { [key: string]: string }
  /** array of string */ tags?: string[]
  /** array of literals */ modes?: Array<'a' | 'b'>
  /** array of objects */ points?: Point[]
  /** readonly array */ ro?: readonly string[]
  /** tuple */ pair?: [number, number]
  /** named tuple */ range?: [min: number, max: number]
  /** Date */ date?: Date
  /** CSSProperties */ style?: React.CSSProperties
  /** Map */ map?: Map<string, number>
  /** Promise */ prom?: Promise<void>
  /** unknown */ unk?: unknown
  /** any */ anything?: any
  /** union of object and string */ mix?: string | Point
  /** union of string | number */ sn?: string | number
  /** intersection */ inter?: Point & { z: number }
  /** keyof */ key?: keyof Point
  /** indexed access */ ia?: Point['x']
  /** Omit */ omitted?: Omit<Point, 'x'>
  /** Pick */ picked?: Pick<Point, 'x'>
  /** Partial */ part?: Partial<Point>
  /** Required */ reqd?: Required<Point>
  /** Parameters */ params?: Parameters<(a: string) => void>
  /** deprecated @deprecated use size */ old?: string
  /** with default @default 'md' */ withDefault?: Size
  /** generic array alias */ gen?: Array<Record<string, unknown>>
  /** union with function */ fnOrStr?: string | (() => string)
  /** bigint/symbol */ big?: bigint
  /** null */ nul?: null
  /** void callback with union param */ onSelect?: (k: 'a' | 'b') => void
}
export function Probe(props: ProbeProps) { return <div /> }

export type GenericProps<T> = { value: T; items: T[]; onPick: (t: T) => void; render: (t: T) => React.ReactNode }
export function Generic<T extends string>(props: GenericProps<T>) { return <div /> }

